import type { Metadata } from "next";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import RevealOnScroll from "@/components/RevealOnScroll";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: {
    default: site.navbar.seo.title,
    template: `%s | ${site.navbar.brand.name}`,
  },
  description: site.navbar.seo.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

/*
 * Runs before the first paint: the `motion` class hides `[data-reveal]` / `[data-intro]` elements until
 * RevealOnScroll plays them, so they don't flash in and then disappear on hydration. If the app script
 * never starts (blocked / failed JS), the class is removed again so no content stays hidden.
 */
const motionScript = `(function(d){if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;d.classList.add("motion");setTimeout(function(){if(!window.__revealReady)d.classList.remove("motion")},3500)})(document.documentElement)`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    // suppressHydrationWarning: the inline script adds the `motion` class before React hydrates.
    <html
      lang={site.navbar.seo.lang}
      data-scroll-behavior="smooth"
      // --u is one design pixel: 1px below 1024px, then the 1688px mockup scaled to the screen, capped at 1920px
      // (120rem, not 1920px: Tailwind sorts px breakpoints before rem ones, so a px value would lose to lg:).
      // --section-space is the space above and below every section; --text-min is the smallest desktop text
      // (11px at 1440px, scaling with the screen below that). Tailwind v4 leaves buttons on the default cursor,
      // so everything clickable gets the pointer (in :where(), so a cursor-* class on the element still wins).
      className={`${fontVariables} overflow-x-clip scroll-smooth antialiased selection:bg-maroon selection:text-white motion-reduce:scroll-auto [--u:1px] lg:[--u:calc(100vw/1688)] min-[120rem]:[--u:calc(1920px/1688)] [--section-space:48px] md:[--section-space:56px] lg:[--section-space:min(5vw,72px)] [--text-min:min(11px,0.7639vw)] [:where(&)_:where(a,button:not(:disabled),[role=button],[role=tab],select,summary,label:has(select),input[type=date],input[type=submit])]:cursor-pointer [:where(&)_:where(button:disabled)]:cursor-not-allowed [&.motion_:is([data-reveal]:not([data-revealed]),[data-intro]:not([data-played],[data-intro=settle]))]:opacity-0 motion-reduce:**:transition-none motion-reduce:**:after:transition-none`}
      suppressHydrationWarning
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
        <script dangerouslySetInnerHTML={{ __html: motionScript }} />
      </head>
      <body className="overflow-x-clip bg-white font-body text-ink">
        <RevealOnScroll />
        {/* Each section caps its own content at 1920px; their backgrounds still run the full screen width. */}
        <div className="flex min-h-screen flex-col">
          <Navbar />
          <main className="flex-1">
            <ScrollToTop>{children}</ScrollToTop>
          </main>
          <Footer />
        </div>
      </body>
    </html>
  );
}
